const campaignStatuses = ['Planned','Active','Paused','Complete','Archived'];
const postStatuses = ['Idea','Draft','Review','Scheduled','Published','Archived','Planned'];
const leadStages = ['New','Engaged','Replied','Booked','Qualified','Proposal','Won','Lost','Nurture','Opted Out'];

function clean(value, fallback = '') {
  if (value === undefined || value === null || value === '') return fallback;
  return value;
}
function num(value) {
  const n = Number(value);
  return Number.isFinite(n) ? n : 0;
}

return items.map((item) => {
  const j = item.json;
  const warnings = [];
  const normalized = {
    test_case: clean(j.test_case, 'lead_signal'),
    campaign_id: clean(j.campaign_id, 'LAS-2026-001'),
    campaign_name: clean(j.campaign_name, 'LinkedIn Authority dogfood campaign'),
    campaign_status: clean(j.campaign_status, 'Active'),
    owner: clean(j.owner, 'Robert'),
    start_date: clean(j.start_date, '2026-05-23'),
    target_buyer: clean(j.target_buyer, 'Founders and service operators'),
    core_problem: clean(j.core_problem, 'LinkedIn activity is not turning into business conversations'),
    cta_label: clean(j.cta_label, 'Request the LinkedIn Authority Setup'),
    cta_url: clean(j.cta_url, 'DECISION_NEEDED'),
    post_id: clean(j.post_id, 'POST-001'),
    post_status: clean(j.post_status, 'Planned'),
    post_date: clean(j.post_date, ''),
    post_url: clean(j.post_url, ''),
    content_type: clean(j.content_type, 'Authority Post'),
    working_title: clean(j.working_title, 'Content should create business conversations, not just activity'),
    comments_worth_replying: num(j.comments_worth_replying),
    connection_requests_sent: num(j.connection_requests_sent),
    replies: num(j.replies),
    calls_booked: num(j.calls_booked),
    post_hours_spent: num(j.post_hours_spent ?? j.hours_spent),
    lead_id: clean(j.lead_id, ''),
    contact_name: clean(j.contact_name, ''),
    company: clean(j.company, ''),
    lead_source: clean(j.lead_source, 'LinkedIn Comment'),
    signal: clean(j.signal, ''),
    stage: clean(j.stage, 'New'),
    first_contact_date: clean(j.first_contact_date, ''),
    estimated_opportunity_value: num(j.estimated_opportunity_value),
    next_follow_up_date: clean(j.next_follow_up_date, ''),
    next_action: clean(j.next_action, ''),
    lead_hours_spent: num(j.lead_hours_spent),
    sender_name: clean(j.sender_name, 'Robert'),
    business_name: clean(j.business_name, 'Uncle Robert Consulting'),
    unsafe_claim_text: clean(j.unsafe_claim_text, '')
  };

  if (!campaignStatuses.includes(normalized.campaign_status)) {
    warnings.push(`Unknown campaign status: ${normalized.campaign_status}`);
    normalized.campaign_status = 'Planned';
  }
  if (!postStatuses.includes(normalized.post_status)) {
    warnings.push(`Unknown post status: ${normalized.post_status}`);
    normalized.post_status = 'Review';
  }
  if (!leadStages.includes(normalized.stage)) {
    warnings.push(`Unknown lead stage: ${normalized.stage}`);
    normalized.stage = 'New';
  }
  if (normalized.cta_url === 'DECISION_NEEDED') warnings.push('CTA URL still needs a destination decision.');
  if (normalized.lead_id && !normalized.next_follow_up_date) warnings.push('Lead exists but next follow-up date is missing.');

  return { json: { ...j, normalized, normalization_warnings: warnings } };
});

const unsafeTerms = [
  'guaranteed',
  'proven',
  'instant roi',
  'immediate roi',
  'algorithm rewards',
  'predictable clients',
  'predictable source of clients',
  'revenue in 48 hours',
  'leads in 48 hours',
  'generate measurable leads in under 48 hours'
];

return items.map((item) => {
  const n = item.json.normalized || item.json;
  const text = Object.values(n).filter(v => typeof v === 'string').join(' ').toLowerCase();
  const extra = String(n.unsafe_claim_text || '').toLowerCase();
  const found = unsafeTerms.filter(term => text.includes(term) || extra.includes(term));
  const claim_check_status = found.length ? 'Needs Review - claim language found' : 'Pass - no guarantee claims in generated fields';
  const claim_check_notes = found.length ? `Review these terms before public use: ${found.join(', ')}` : 'No blocked claim terms found in this test payload.';
  const workflow_run_status = found.length ? 'Ready For Review' : (n.cta_url === 'DECISION_NEEDED' ? 'Ready For Review' : 'Passed');
  return { json: { ...item.json, claim_check_status, claim_check_notes, blocked_claim_terms: found, workflow_run_status } };
});

return items.map((item) => {
  const n = item.json.normalized;
  const suggested_reply = 'Thanks for engaging with that post. I am testing a simple LinkedIn authority loop for founders who want content to create real business conversations, not just activity. Are you trying to use LinkedIn for leads right now, or more for credibility?';
  const follow_up_task = {
    task_title: `Follow up on ${n.lead_id || n.post_id} - ${n.campaign_name}`,
    task_owner: n.owner,
    task_due_date: n.next_follow_up_date || 'DECISION_NEEDED',
    task_context: n.signal || `Review LinkedIn signal for ${n.post_id}`,
    suggested_reply,
    source_post_id: n.post_id,
    lead_id: n.lead_id || '',
    manual_fallback: 'Add the record manually to the ROI tracker workbook and set the next follow-up date.'
  };
  return { json: { ...item.json, follow_up_task } };
});

return items.map((item) => {
  const n = item.json.normalized;
  const owner_notification = [
    'LinkedIn Authority follow-up needed',
    '',
    `Campaign: ${n.campaign_name}`,
    `Lead: ${n.contact_name || 'No contact name yet'} / ${n.company || 'No company yet'}`,
    `Signal: ${n.signal || 'No signal text captured'}`,
    `Next action: ${n.next_action || 'DECISION_NEEDED'}`,
    `Due: ${n.next_follow_up_date || 'DECISION_NEEDED'}`,
    `Source post: ${n.post_id}`,
    `CTA URL: ${n.cta_url}`,
    `Claim check: ${item.json.claim_check_status}`
  ].join('\n');
  return { json: { ...item.json, owner_notification } };
});

return items.map((item) => {
  const final_local_review = {
    workflow_name: 'LinkedIn Authority System - Intake to Follow-Up Tracker',
    workflow_run_status: item.json.workflow_run_status,
    normalized_intake: item.json.normalized,
    normalization_warnings: item.json.normalization_warnings,
    claim_check: {
      status: item.json.claim_check_status,
      notes: item.json.claim_check_notes,
      blocked_terms: item.json.blocked_claim_terms
    },
    tracker_payloads: {
      campaign_row: item.json.campaign_row,
      post_row: item.json.post_row,
      lead_row: item.json.lead_row,
      weekly_review_hint: item.json.weekly_review_hint
    },
    follow_up_task: item.json.follow_up_task,
    owner_notification: item.json.owner_notification,
    activation_note: 'Manual-trigger proof only. No send/post/write nodes are active in this v1 lane.'
  };
  return { json: { final_local_review } };
});

return items.map((item) => {
  const payload = item.json.final_local_review?.tracker_payloads || {};
  const json = JSON.stringify(payload);
  const tracker_write_payload_b64 = Buffer.from(json, 'utf8').toString('base64');
  return { json: { ...item.json, tracker_write_payload_b64 } };
});

return items.map((item) => ({
  json: {
    ...item.json,
    tracker_write_result: {
      status: 'Skipped in n8n',
      reason: 'executeCommand node type is unavailable in this n8n instance',
      fallback: 'Use automation/write-tracker-payload.py directly, or use the Google Sheets connector lane.'
    },
    command_exit_code: 0
  }
}));

return items.map((item) => {
  if (item.json.tracker_write_result) {
    return { json: { tracker_write_result: item.json.tracker_write_result, command_exit_code: item.json.command_exit_code ?? 0 } };
  }
  let parsed = {};
  try { parsed = JSON.parse(item.json.stdout || '{}'); } catch (error) { parsed = { parse_error: error.message, stdout: item.json.stdout, stderr: item.json.stderr }; }
  return { json: { tracker_write_result: parsed, command_exit_code: item.json.exitCode ?? 0 } };
});

const payloads = items[0]?.json?.final_local_review?.tracker_payloads || {};
const rows = [
  { sheet_tab: 'Campaigns', match_key_column: 'Campaign ID', match_key: payloads.campaign_row?.['Campaign ID'], row: payloads.campaign_row },
  { sheet_tab: 'Posts', match_key_column: 'Post ID', match_key: payloads.post_row?.['Post ID'], row: payloads.post_row },
  { sheet_tab: 'Lead Follow-Up', match_key_column: 'Lead ID', match_key: payloads.lead_row?.['Lead ID'], row: payloads.lead_row },
  { sheet_tab: 'Weekly Review', match_key_column: 'Campaign ID', match_key: payloads.weekly_review_hint?.['Campaign ID'], row: payloads.weekly_review_hint }
];
return rows
  .filter((entry) => entry.row && entry.match_key)
  .map((entry) => ({
    json: {
      google_sheets_status: 'Ready For Credential Mapping',
      spreadsheet_id: 'DECISION_NEEDED',
      ...entry,
      ...entry.row
    }
  }));
